class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        n = len(s)
        maxlen = -1

        # For each character, collect all run lengths
        runs = defaultdict(list)  # {ch: [run lengths]}
        i = 0
        while i < n:
            ch = s[i]
            j = i
            while j < n and s[j] == ch:
                j += 1
            runs[ch].append(j - i)
            i = j

        for ch in runs:
            # To find runs that appear at least 3 times, we consider the sorted runs of lengths
            arr = sorted(runs[ch], reverse=True)
            for k in range(arr[0], 0, -1):
                cnt = 0
                for a in arr:
                    cnt += a // k
                if cnt >= 3:
                    maxlen = max(maxlen, k)
                    break  # For this letter, this is the max possible, so skip smaller lengths

        return maxlen
